export const DOMINO_HEIGHT = 1.5;
export const DOMINO_WIDTH = 0.6;
export const DOMINO_THICKNESS = 0.1;

const DEFAULT_START_DELAY = 0.15;
const DEFAULT_FALL_DUR = 0.4;

function smoothstep(x) {
  return x * x * (3 - 2 * x);
}

/**
 * Lay `count` thin-box dominoes along an open CatmullRomCurve3 built from
 * `curvePoints`, at equal arc-length spacing `gap`. Each domino is oriented
 * to face the next one. Returns a THREE.Group whose children are pivot
 * groups (one per domino) ready to be driven by animateDominoes().
 */
export function layDominoes(curvePoints, count, gap) {
  if (!Array.isArray(curvePoints) || curvePoints.length < 2) {
    throw new Error('curvePoints must contain at least two points');
  }
  if (!Number.isFinite(count) || count < 1 || !Number.isInteger(count)) {
    throw new Error('count must be a positive integer');
  }

  const maxGap = 0.8 * DOMINO_HEIGHT; // a real cascade is only plausible below this
  if (!(gap > 0 && gap < maxGap)) {
    throw new Error(
      `gap must satisfy 0 < gap < ${maxGap} (0.8 * height ${DOMINO_HEIGHT}); got ${gap}`
    );
  }

  const curve = new THREE.CatmullRomCurve3(
    curvePoints.map((p) => p.clone()),
    false // open curve
  );
  const totalLength = curve.getLength();

  // Equal arc-length sampling along the curve.
  const positions = [];
  for (let i = 0; i < count; i++) {
    const u = totalLength > 0 ? Math.min(1, (i * gap) / totalLength) : 0;
    positions.push(curve.getPointAt(u));
  }

  const group = new THREE.Group();
  group.name = 'dominoes';
  group.userData = {
    count,
    gap,
    startDelay: DEFAULT_START_DELAY,
    fallDur: DEFAULT_FALL_DUR,
  };

  const geometry = new THREE.BoxGeometry(
    DOMINO_WIDTH,
    DOMINO_HEIGHT,
    DOMINO_THICKNESS
  );

  for (let i = 0; i < count; i++) {
    const pos = positions[i];

    // Face the next domino; the last one keeps its predecessor's heading.
    let forward;
    if (i < count - 1) {
      forward = new THREE.Vector3().subVectors(positions[i + 1], pos);
    } else {
      forward = new THREE.Vector3().subVectors(pos, positions[i - 1]);
    }
    if (forward.lengthSq() === 0) forward.set(0, 0, 1);
    forward.normalize();

    // Pivot sits on the domino's bottom-front edge (the hinge it topples over).
    const pivot = new THREE.Group();
    pivot.name = `domino-${i}`;
    pivot.position.copy(pos).addScaledVector(forward, DOMINO_THICKNESS / 2);

    // Orient the pivot so local +Z points at the next domino.
    const dummy = new THREE.Object3D();
    dummy.position.copy(pivot.position);
    dummy.lookAt(pivot.position.clone().add(forward));
    pivot.quaternion.copy(dummy.quaternion);

    pivot.userData = { index: i, startDelay: DEFAULT_START_DELAY, fallDur: DEFAULT_FALL_DUR };

    // Mesh centered inside the pivot so the box's bottom-front edge coincides
    // with the pivot origin: rotating pivot.rotation.x tips it forward.
    const mesh = new THREE.Mesh(geometry);
    mesh.position.set(0, DOMINO_HEIGHT / 2, -DOMINO_THICKNESS / 2);
    mesh.userData.index = i;

    pivot.add(mesh);
    group.add(pivot);
  }

  return group;
}

/**
 * Topple angle of domino `i` at time `t`.
 * Domino i begins falling at i * startDelay, then rotates about its
 * bottom-front edge from 0 to PI/2 with smoothstep easing over fallDur.
 * Clamped to 0 before its start time and to PI/2 once fully fallen.
 */
export function toppleState(i, t, { startDelay = DEFAULT_START_DELAY, fallDur = DEFAULT_FALL_DUR } = {}) {
  const start = i * startDelay;
  if (t <= start) return 0;
  const raw = Math.min(1, (t - start) / fallDur);
  return (Math.PI / 2) * smoothstep(raw);
}

/**
 * Apply the topple timeline to every pivot group in `group`
 * (as produced by layDominoes).
 */
export function animateDominoes(group, t) {
  const { startDelay = DEFAULT_START_DELAY, fallDur = DEFAULT_FALL_DUR } =
    group.userData ?? {};
  group.children.forEach((pivot, i) => {
    pivot.rotation.x = toppleState(i, t, { startDelay, fallDur });
  });
}
"})
