import * as THREE from 'three';
import {
  layDominoes,
  toppleState,
  animateDominoes,
  DOMINO_HEIGHT,
  DOMINO_WIDTH,
  DOMINO_THICKNESS,
} from '../src/dominoes.js';

// Straight ground-level curve so chord distance == arc length exactly.
const STRAIGHT_POINTS = [
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(10, 0, 0),
];

const COUNT = 8;
const GAP = 0.9; // < 0.8 * height = 1.2

function makeGroup() {
  return layDominoes(STRAIGHT_POINTS, COUNT, GAP);
}

describe('layDominoes', () => {
  it('rejects gaps too wide for a plausible cascade', () => {
    expect(() => layDominoes(STRAIGHT_POINTS, COUNT, 0.8 * DOMINO_HEIGHT)).toThrow();
    expect(() => layDominoes(STRAIGHT_POINTS, COUNT, 1.3)).toThrow();
    expect(() => layDominoes(STRAIGHT_POINTS, COUNT, GAP)).not.toThrow();
  });

  it('creates one pivot group per domino', () => {
    const group = makeGroup();
    expect(group.children.length).toBe(COUNT);
    expect(group.children[3].name).toBe('domino-3');
  });
});

describe('toppleState', () => {
  it('is 0 everywhere at t = 0', () => {
    for (let i = 0; i < COUNT; i++) {
      expect(toppleState(i, 0)).toBe(0);
      animateDominoes(makeGroup(), 0); // sanity: no throw
    }
    const group = makeGroup();
    animateDominoes(group, 0);
    for (const pivot of group.children) {
      expect(pivot.rotation.x).toBe(0);
    }
  });

  it('starts dominoes 0-2 by t = 0.5 but not domino 5 (default delays)', () => {
    const t = 0.5;
    const angles = [];
    for (let i = 0; i < COUNT; i++) angles.push(toppleState(i, t));

    for (let i = 0; i <= 2; i++) {
      expect(angles[i]).toBeGreaterThan(0);
    }
    expect(angles[5]).toBe(0);

    const group = makeGroup();
    animateDominoes(group, t);
    for (let i = 0; i <= 2; i++) {
      expect(group.children[i].rotation.x).toBeGreaterThan(0);
    }
    expect(group.children[5].rotation.x).toBe(0);
